package com.kisanmitra.upload;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.net.URI; import java.net.http.HttpClient; import java.net.http.HttpRequest; import java.net.http.HttpResponse; import java.util.*;
@RestController @RequestMapping("/api/upload") public class UploadController {
 @Value("${SUPABASE_URL:}") String url; @Value("${SUPABASE_SERVICE_ROLE_KEY:}") String key; @Value("${SUPABASE_STORAGE_BUCKET:listing-images}") String bucket;
 @PostMapping("/images") public Map<String,Object> images(@RequestParam("images") MultipartFile[] files,Authentication auth)throws Exception { if(auth==null)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED); List<String> out=new ArrayList<>(); for(MultipartFile f:files){String name=UUID.randomUUID()+"-"+Optional.ofNullable(f.getOriginalFilename()).orElse("image").replaceAll("[^a-zA-Z0-9._-]","_"); String endpoint=url+"/storage/v1/object/"+bucket+"/"+name; HttpRequest req=HttpRequest.newBuilder(URI.create(endpoint)).header("Authorization","Bearer "+key).header("apikey",key).header("Content-Type",Optional.ofNullable(f.getContentType()).orElse("application/octet-stream")).PUT(HttpRequest.BodyPublishers.ofByteArray(f.getBytes())).build(); HttpResponse<String> res=HttpClient.newHttpClient().send(req,HttpResponse.BodyHandlers.ofString()); if(res.statusCode()/100!=2)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_GATEWAY,"Storage upload failed: "+res.body()); out.add(url+"/storage/v1/object/public/"+bucket+"/"+name);} return Map.of("success",true,"data",Map.of("urls",out)); }
}
